47	diff --git a/src/common/people/gait.ts b/src/common/people/gait.ts
48	new file mode 100644
49	index 0000000..3efa88b
50	--- /dev/null
51	+++ b/src/common/people/gait.ts
52	@@ -0,0 +1,44 @@
53	+import { CONFIG } from '../../config';
54	+
55	+/* =====================================================================
56	+   DÁNG ĐI / DÁNG CHẠY NGƯỜI ĐI BỘ — bản CPU của shader trong material.ts (spec §5, G6, G7).
57	+   Shader mới là chỗ chạy thật; file này giữ cùng công thức để unit test kiểm (tests/people-unit/gait.test.ts)
58	+   và để code dựng tính nhịp bước (aVar.w) cho từng người. Đổi công thức ở đây thì sửa cả PP_GLSL_ANGLES trong material.ts.
59	+   Góc dương = đưa về phía trước (người hướng +X, quay quanh trục Z). φ là pha chu kỳ hai bước:
60	+   chân trái φ, chân phải φ + π, tay ngược pha chân cùng bên. Trộn đi ↔ chạy theo biên độ: run = smoothstep(0,42; 0,6; A).
61	+   ===================================================================== */
62	+export type PersonKind = 'walk' | 'run' | 'stand';
63	+export type PersonPart = 'legL' | 'legR' | 'armL' | 'armR';
64	+const P = CONFIG.people;
65	+
66	+const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
67	+const smoothstep = (a: number, b: number, x: number) => { const t = Math.min(1, Math.max(0, (x - a) / (b - a))); return t * t * (3 - 2 * t); };
68	+/* Mức chạy 0..1 theo biên độ hông (đi 0,34 → 0, chạy 0,6 → 1) */
69	+export const ppRunMix = (amp: number) => smoothstep(0.42, 0.6, amp);
70	+/* Biên độ hông theo kiểu người */
71	+export const ppAmp = (kind: PersonKind) => (kind === 'walk' ? P.walk.amp : kind === 'run' ? P.run.amp : 0);
72	+
73	+/* Nhịp (rad/s của φ). Đi: chân trụ không trượt ⇔ ω · bước / 2π = v. Chạy: nhịp cố định, người nhỏ bước nhanh hơn. Đứng: 0 */
74	+export function ppCadence(kind: PersonKind, speed: number, scale: number): number {
75	+  if (kind === 'walk') return (2 * Math.PI * speed) / (4 * P.legLength * scale * Math.sin(P.walk.amp));
76	+  if (kind === 'run') return P.run.cadence / Math.sqrt(scale);
77	+  return 0;
78	+}
79	+
80	+/* Quãng đường một chu kỳ hai bước (m): mỗi bước chân trụ quét dây cung 2·L·sin A. Chạy ở tỉ lệ 1 ≈ 1,94 m, khớp 2,6–3,0 m/s ở 1,4 chu kỳ/giây */
81	+export function ppStride(kind: PersonKind, scale: number): number {
82	+  return kind === 'stand' ? 0 : 4 * P.legLength * scale * Math.sin(ppAmp(kind));
83	+}
84	+
85	+/* Góc khớp: root = hông / vai, joint = gối (≤ 0, gập về sau) / khuỷu (≥ 0, gập về trước). Không tính tư thế chụp ảnh (cờ, chỉ có trong shader) */
86	+export function ppAngles(part: PersonPart, amp: number, phase: number): { root: number; joint: number } {
87	+  const A = amp, run = ppRunMix(A);
88	+  if (part === 'legL' || part === 'legR') {
89	+    const f = part === 'legL' ? phase : phase + Math.PI;
90	+    const sw = Math.max(0, Math.cos(f - 0.35)), sr = Math.max(0, Math.cos(f + 0.45));   // đi: gập gối khi đưa chân lên trước; chạy: gập sớm và sâu hơn
91	+    const knee = A * 2 * sw * sw + (A >= 0.01 ? 0.06 : 0);
92	+    return { root: A * Math.sin(f) + lerp(0.12 * A, 0.22, run), joint: -lerp(knee, 0.38 + 1.5 * sr * sr, run) };
93	+  }
94	+  const f = part === 'armL' ? phase + Math.PI : phase;
95	+  return { root: A * (0.65 + run * 0.5) * Math.sin(f) - 0.05, joint: 0.16 + run * 1.25 + A * 0.35 * Math.max(0, Math.sin(f)) };
96	+}
97	diff --git a/src/common/people/kinds.ts b/src/common/people/kinds.ts
98	new file mode 100644
99	index 0000000..9b7b95f
100	--- /dev/null
101	+++ b/src/common/people/kinds.ts
102	@@ -0,0 +1,44 @@
103	+import { CONFIG } from '../../config';
104	+import { rng } from '../math';
105	+import type { PersonKind } from './gait';
106	+
107	+/* =====================================================================
108	+   CHIA KIỂU NGƯỜI (spec G8, §7) — chọn theo chỉ số trên danh sách người đang có, tổng số không đổi.
109	+   Dùng rng(seed) riêng (không gọi rand(), không đụng rnd của cầu). Số người mỗi kiểu = làm tròn n × CONFIG.people.mix.
110	+   - Người đi cùng (đi đôi hoặc trẻ em) i luôn theo người i − 1; người i − 1 đi bộ một mình (không chạy, không đứng, không đi cùng ai).
111	+   - Trẻ em: tỉ lệ childScale, luôn là người đi cùng. Người chụp ảnh: chỉ trong số người đứng.
112	+   - flags = tổng cờ PP_FLAG (khớp aVar.z trong material.ts).
113	+   ===================================================================== */
114	+export const PP_FLAG = { hat: 1, pack: 2, photo: 4 } as const;
115	+export interface PersonInfo { kind: PersonKind; scale: number; flags: number; phase: number; follow: number /* chỉ số người mình đi cùng, −1 nếu không */ }
116	+
117	+/* Xáo trộn Fisher–Yates bằng bộ sinh r */
118	+function ppShuffle<T>(a: T[], r: () => number): T[] {
119	+  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
120	+  return a;
121	+}
122	+
123	+export function ppAssignKinds(n: number, seed: number, opts?: { run?: boolean }): PersonInfo[] {
124	+  const P = CONFIG.people, M = P.mix, r = rng(seed), [s0, s1] = P.adultScale;
125	+  const out: PersonInfo[] = Array.from({ length: n }, () => ({ kind: 'walk' as PersonKind, scale: s0 + r() * (s1 - s0), flags: 0, phase: r() * Math.PI * 2, follow: -1 }));
126	+  // người đi cùng: chọn chỉ số i ≥ 1 sao cho i − 1 và i + 1 không cũng là người đi cùng (người dẫn không đi cùng ai)
127	+  const comp = new Set<number>(), nComp = Math.round(n * M.companion);
128	+  for (const i of ppShuffle(Array.from({ length: Math.max(0, n - 1) }, (_, k) => k + 1), r)) {
129	+    if (comp.size >= nComp) break;
130	+    if (!comp.has(i - 1) && !comp.has(i + 1)) comp.add(i);
131	+  }
132	+  const compList = [...comp].sort((a, b) => a - b);
133	+  for (const i of compList) out[i].follow = i - 1;
134	+  for (const i of ppShuffle(compList.slice(), r).slice(0, Math.round(compList.length * M.child))) out[i].scale = P.childScale;
135	+  // người đứng và người chạy: lấy từ những người không đi cùng và không dẫn ai
136	+  const free = ppShuffle(out.map((_, i) => i).filter((i) => !comp.has(i) && !comp.has(i + 1)), r);
137	+  const nStand = Math.min(free.length, Math.round(n * M.stand)), nRun = opts?.run === false ? 0 : Math.min(free.length - nStand, Math.round(n * M.run));
138	+  const stand = free.slice(0, nStand);
139	+  for (const i of stand) out[i].kind = 'stand';
140	+  for (const i of free.slice(nStand, nStand + nRun)) out[i].kind = 'run';
141	+  // cờ: nón lá, ba lô trên mọi người; chụp ảnh trong số người đứng
142	+  for (const i of ppShuffle(out.map((_, k) => k), r).slice(0, Math.round(n * M.hat))) out[i].flags |= PP_FLAG.hat;
143	+  for (const i of ppShuffle(out.map((_, k) => k), r).slice(0, Math.round(n * M.pack))) out[i].flags |= PP_FLAG.pack;
144	+  for (const i of ppShuffle(stand.slice(), r).slice(0, Math.round(stand.length * M.photo))) out[i].flags |= PP_FLAG.photo;
145	+  return out;
146	+}
147	diff --git a/src/common/people/material.ts b/src/common/people/material.ts
148	new file mode 100644
149	index 0000000..770dda6
150	--- /dev/null
151	+++ b/src/common/people/material.ts
152	@@ -0,0 +1,79 @@
153	+import * as THREE from 'three';
154	+import { CONFIG } from '../../config';
155	+import { shared } from '../../core/shared';
156	+
157	+/* =====================================================================
158	+   VẬT LIỆU NGƯỜI ĐI BỘ — một vật liệu dùng chung cho mọi hệ người (spec G5–G8, §5), theo patchPerson của bản dựng thử.
159	+   Tay chân vung trong vertex shader theo shared.uTime, không cập nhật đỉnh trên CPU. Công thức góc khớp giống hệt gait.ts (ppAngles).
160	+   Thuộc tính instance (bên dựng gắn vào hình học của từng InstancedMesh):
161	+   - aVar (vec4): x pha φ0 (rad), y biên độ hông A (0 đứng, walk.amp, run.amp), z cờ (1 nón lá, 2 ba lô, 4 chụp ảnh), w nhịp (rad/s, ppCadence)
162	+   - aPants (vec3): màu quần tuyến tính; màu áo qua instanceColor (setColorAt — bắt buộc gọi để có USE_INSTANCING_COLOR)
163	+   Người không đổ bóng, không vào phản chiếu (spec §6) nên không có vật liệu bóng riêng. Không emissive, không texture.
164	+   Không thêm vào tập bóc mặt cắt hầm (cutaway.ts): người không đứng trong vùng bóc, vật liệu người cũ cũng không có trong tập đó.
165	+   ===================================================================== */
166	+const P = CONFIG.people;
167	+const f = (x: number) => x.toFixed(4);   // số → hằng GLSL
168	+
169	+/* pAngles: x góc khớp gốc (hông / vai), y góc khớp giữa (gối / khuỷu); dương = đưa về phía trước. Bản CPU: gait.ts ppAngles */
170	+const VS_HEAD = /* glsl */`
171	+attribute float aPart;
172	+attribute float aSeg;
173	+attribute float aPivot;
174	+attribute float aPivot2;
175	+attribute float aMask;
176	+attribute vec3 aFix;
177	+attribute vec4 aVar;
178	+attribute vec3 aPants;
179	+uniform float uTime;
180	+float pFlag( float b ) { return mod( floor( aVar.z / b ), 2.0 ); }
181	+float pRunMix() { return smoothstep( 0.42, 0.6, aVar.y ); }
182	+float pPhase() { return uTime * aVar.w + aVar.x; }
183	+vec2 pAngles() {
184	+  float A = aVar.y, ph = pPhase(), run = pRunMix();
185	+  if ( aPart > 0.5 && aPart < 2.5 ) {
186	+    float fl = aPart < 1.5 ? ph : ph + 3.14159265;
187	+    float sw = max( 0.0, cos( fl - 0.35 ) ), sr = max( 0.0, cos( fl + 0.45 ) );   // đi: gập gối khi đưa chân lên trước; chạy: gập sớm và sâu hơn
188	+    return vec2( A * sin( fl ) + mix( 0.12 * A, 0.22, run ), -mix( A * 2.0 * sw * sw + 0.06 * step( 0.01, A ), 0.38 + 1.5 * sr * sr, run ) );
189	+  }
190	+  if ( aPart > 2.5 && aPart < 4.5 ) {
191	+    float fa = aPart < 3.5 ? ph + 3.14159265 : ph;
192	+    if ( aPart > 3.5 && pFlag( 4.0 ) > 0.5 ) return vec2( ${f(P.photo.shoulder)}, ${f(P.photo.elbow)} );   // giơ tay phải chụp ảnh
193	+    return vec2( A * ( 0.65 + run * 0.5 ) * sin( fa ) - 0.05, 0.16 + run * 1.25 + A * 0.35 * max( 0.0, sin( fa ) ) );
194	+  }
195	+  return vec2( 0.0 );
196	+}
197	+vec2 pRot( vec2 p, float a ) { float c = cos( a ), s = sin( a ); return vec2( p.x * c - p.y * s, p.x * s + p.y * c ); }
198	+`;
199	+// pháp tuyến quay cùng khớp (beginnormal_vertex chạy trước begin_vertex nên ppA dùng lại được)
200	+const VS_NORMAL = /* glsl */`#include <beginnormal_vertex>
201	+vec2 ppA = pAngles();
202	+float ppLean = ( aPart < 0.5 || aPart > 2.5 ) ? -${f(P.run.lean)} * pRunMix() : 0.0;
203	+objectNormal.xy = pRot( objectNormal.xy, ppA.x + ( aSeg > 0.5 ? ppA.y : 0.0 ) + ppLean );`;
204	+const VS_POS = /* glsl */`#include <begin_vertex>
205	+if ( aSeg > 0.5 ) transformed.xy = pRot( transformed.xy - vec2( 0.0, aPivot2 ), ppA.y ) + vec2( 0.0, aPivot2 );
206	+transformed.xy = pRot( transformed.xy - vec2( 0.0, aPivot ), ppA.x ) + vec2( 0.0, aPivot );
207	+transformed.xy = pRot( transformed.xy - vec2( 0.0, ${f(P.legLength)} ), ppLean ) + vec2( 0.0, ${f(P.legLength)} );   // chạy: thân, đầu, tay đổ về trước quanh hông
208	+if ( aPart > 4.5 && aPart < 5.5 && pFlag( 1.0 ) < 0.5 ) transformed = vec3( 0.0 );   // không đội nón: thu về gốc (tam giác suy biến)
209	+if ( aPart > 5.5 && pFlag( 2.0 ) < 0.5 ) transformed = vec3( 0.0 );                  // không đeo ba lô
210	+float ppPh = pPhase(), ppMove = step( 0.01, aVar.y );
211	+transformed.y += mix( ${f(P.bob.walk)} * cos( 2.0 * ppPh ) - ${f(P.bob.walk)}, ${f(P.bob.run)} * ( 0.5 - 0.5 * cos( 2.0 * ppPh ) ), pRunMix() ) * ppMove;   // đi: thấp nhất khi hai chân dang rộng; chạy: bật lên giữa hai bước
212	+transformed.z += ${f(P.sway)} * sin( ppPh ) * ppMove * smoothstep( 0.3, 1.6, transformed.y );   // lắc vai nhẹ sang hai bên`;
213	+const VS_COLOR = /* glsl */`#include <color_vertex>
214	+#ifdef USE_INSTANCING_COLOR
215	+vColor.rgb = aMask < 0.5 ? aFix : ( aMask < 1.5 ? instanceColor.rgb : aPants );   // cố định / áo / quần
216	+#endif`;
217	+
218	+let mat: THREE.MeshStandardMaterial | null = null;
219	+/* Một vật liệu cho mọi hệ người (tạo lần đầu gọi) */
220	+export function ppMaterial(): THREE.MeshStandardMaterial {
221	+  if (mat) return mat;
222	+  const m = new THREE.MeshStandardMaterial({ roughness: P.roughness });
223	+  m.name = 'peopleWalk';
224	+  m.onBeforeCompile = (s) => {
225	+    s.uniforms.uTime = shared.uTime;
226	+    s.vertexShader = VS_HEAD + s.vertexShader.replace('#include <beginnormal_vertex>', VS_NORMAL).replace('#include <begin_vertex>', VS_POS).replace('#include <color_vertex>', VS_COLOR);
227	+    m.userData.vs = s.vertexShader;
228	+  };
229	+  m.customProgramCacheKey = () => 'peopleWalk';
230	+  return (mat = m);
231	+}
232	diff --git a/src/common/people/shapes.ts b/src/common/people/shapes.ts
233	new file mode 100644
234	index 0000000..b7e0521
235	--- /dev/null
236	+++ b/src/common/people/shapes.ts
237	@@ -0,0 +1,51 @@
238	+import * as THREE from 'three';
239	+import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
240	+import { CONFIG } from '../../config';
241	+
242	+/* =====================================================================
243	+   HÌNH HỌC NGƯỜI ĐI BỘ — một hình gộp cho mọi kiểu người (spec G5, G8): thân, đầu, tóc, hai tay (bắp tay áo cộc + cẳng tay),
244	+   hai chân (đùi + ống quần + giày), nón lá, ba lô. Theo personGeo của bản dựng thử, bớt cạnh để ≤ CONFIG.people.maxVerts đỉnh.
245	+   Mét, tỉ lệ 1: cao ≈ 1,65 m (≈ 1,79 m tính chóp nón), mặt hướng +X, rộng theo Z, chân chạm y = 0. Có index, không uv.
246	+   Thuộc tính đỉnh (shader ở material.ts đọc):
247	+   - aPart: 0 thân/đầu/tóc, 1 chân trái (−Z, vì mặt hướng +X), 2 chân phải (+Z), 3 tay trái, 4 tay phải, 5 nón lá, 6 ba lô (5, 6 bật theo cờ instance)
248	+   - aSeg: 0 đoạn trên, 1 đoạn dưới khớp (quay thêm quanh aPivot2); aPivot: cao độ hông / vai; aPivot2: cao độ gối / khuỷu
249	+   - aMask: 0 màu cố định aFix, 1 áo (instanceColor), 2 quần (aPants); aFix: màu cố định tuyến tính (da, tóc, giày, nón, ba lô)
250	+   ===================================================================== */
251	+export const PP_HIP = 0.86, PP_KNEE = 0.46, PP_SHOULDER = 1.37, PP_ELBOW = 1.1;   // m — cao độ khớp ở tỉ lệ 1
252	+export enum PpPart { Body = 0, LegL = 1, LegR = 2, ArmL = 3, ArmR = 4, Hat = 5, Pack = 6 }
253	+export enum PpMask { Fixed = 0, Shirt = 1, Pants = 2 }
254	+
255	+const C = CONFIG.people.palette;
256	+const cap = (r: number, l: number) => new THREE.CapsuleGeometry(r, l, 2, 6);   // tay chân: 6 cạnh, nắp 2 đoạn
257	+
258	+/* Gắn thuộc tính khớp và màu cho một bộ phận; bỏ uv để mọi phần gộp được */
259	+function ppTag(g: THREE.BufferGeometry, part: PpPart, pivot: number, fix: number, mask: PpMask, seg = 0, pivot2 = 0): THREE.BufferGeometry {
260	+  if (g.getAttribute('uv')) g.deleteAttribute('uv'); g.clearGroups();
261	+  const n = g.getAttribute('position').count, col = new THREE.Color(fix), F = new Float32Array(n * 3);
262	+  for (let i = 0; i < n; i++) { F[i * 3] = col.r; F[i * 3 + 1] = col.g; F[i * 3 + 2] = col.b; }
263	+  const fill = (v: number) => new THREE.BufferAttribute(new Float32Array(n).fill(v), 1);
264	+  g.setAttribute('aPart', fill(part)); g.setAttribute('aSeg', fill(seg)); g.setAttribute('aPivot', fill(pivot)); g.setAttribute('aPivot2', fill(pivot2));
265	+  g.setAttribute('aMask', fill(mask)); g.setAttribute('aFix', new THREE.BufferAttribute(F, 3));
266	+  return g;
267	+}
268	+
269	+/* Dựng mới mỗi lần gọi (không cache): bên gọi giữ một bản dùng chung cho mọi hệ người nếu muốn */
270	+export function ppBuildGeometry(): THREE.BufferGeometry {
271	+  const parts = [
