534	+  const part = arr(g, 'aPart'), seg = arr(g, 'aSeg'), piv = arr(g, 'aPivot'), piv2 = arr(g, 'aPivot2'), mask = arr(g, 'aMask');
535	+  assert.deepEqual([...new Set(part)].sort(), [0, 1, 2, 3, 4, 5, 6]);
536	+  for (let i = 0; i < n; i++) {
537	+    assert.ok(seg[i] === 0 || seg[i] === 1, `aSeg ${seg[i]}`);
538	+    if (seg[i] === 1) assert.ok(part[i] >= 1 && part[i] <= 4, `aSeg = 1 ở aPart ${part[i]}`);
539	+    if (part[i] === 1 || part[i] === 2) { assert.equal(piv[i], F32(PP_HIP)); if (seg[i] === 1) assert.equal(piv2[i], F32(PP_KNEE)); }
540	+    if (part[i] === 3 || part[i] === 4) { assert.equal(piv[i], F32(PP_SHOULDER)); if (seg[i] === 1) assert.equal(piv2[i], F32(PP_ELBOW)); }
541	+    assert.ok([0, 1, 2].includes(mask[i]), `aMask ${mask[i]}`);
542	+  }
543	+  assert.ok(mask.includes(1) && mask.includes(2), 'thiếu đỉnh áo hoặc quần');
544	+});
